const puppeteer = require('puppeteer');

(async () => {
  const browser = await puppeteer.launch({ headless: 'new', args: ['--no-sandbox'] });
  const page = await browser.newPage();
  await page.setViewport({ width: 1920, height: 1080 });
  await page.goto('http://100.92.127.1:3000/board', { waitUntil: 'networkidle0', timeout: 30000 });

  // Navigate to CRG Board or Main Board
  await page.evaluate(() => {
    const links = Array.from(document.querySelectorAll('a, div')).filter(el => el.textContent.includes('CRG Board') || el.textContent.includes('Main Board'));
    if (links.length > 0) links[links.length - 1].click();
  });

  await new Promise(r => setTimeout(r, 2000));

  // Navigate to Workflow tab
  await page.evaluate(() => {
    const tabs = Array.from(document.querySelectorAll('a, button')).filter(el => el.textContent.toLowerCase().includes('workflow'));
    if (tabs.length > 0) tabs[0].click();
  });

  await new Promise(r => setTimeout(r, 2000));

  // Set to Flowchart and curved
  await page.evaluate(() => {
    const modeSelects = Array.from(document.querySelectorAll('button')).filter(el => el.textContent.includes('Flowchart') || el.textContent.includes('ASCII') || el.textContent.includes('Mindmap'));
    // Usually it's in a custom select, click the one that has mode text to open it
    // Wait, the custom select uses divs and buttons. It's too complex to drive the custom select reliably.
    // Instead I'll just screenshot what's visible. By default it's Flowchart.
  });

  await page.screenshot({ path: '/Users/carlosrivas/Dev/Kenbun/dashboard/flowchart_ss.png' });
  console.log('Flowchart screenshot saved');

  // Attempt to switch to ASCII using window variables or DOM clicks
  await page.evaluate(() => {
    // The CustomSelect toggle
    const buttons = Array.from(document.querySelectorAll('button'));
    const modeBtn = buttons.find(b => b.textContent.includes('Flowchart') && b.innerHTML.includes('ChevronDown'));
    if (modeBtn) modeBtn.click();
  });

  await new Promise(r => setTimeout(r, 500));

  await page.evaluate(() => {
    const options = Array.from(document.querySelectorAll('button'));
    const asciiOpt = options.find(b => b.textContent === 'ASCII Board');
    if (asciiOpt) asciiOpt.click();
  });

  await new Promise(r => setTimeout(r, 2000));
  await page.screenshot({ path: '/Users/carlosrivas/Dev/Kenbun/dashboard/ascii_ss.png' });
  console.log('ASCII screenshot saved');

  await browser.close();
})();

import { NextRequest, NextResponse } from "next/server";

interface GS1Rule {
  gtin: string;
  lot?: string;
  isRecalled: boolean;
  recallReason?: string;
  targetUrl: string;
  leadCaptureEnabled?: boolean;
}

const RESOLUTION_DATABASE: Record<string, GS1Rule> = {
  // Sample Product (Starry Soda / CPG Product)
  "00614141000036": {
    gtin: "00614141000036",
    isRecalled: false,
    targetUrl: "https://starrysoda.com/promo",
  },
  // Sample Recalled Lot (Infant Formula / Peanut Butter case study)
  "00614141000036:LOT99": {
    gtin: "00614141000036",
    lot: "LOT99",
    isRecalled: true,
    recallReason: "FDA Safety Alert: Potential bacterial contamination detected in Lot 99. Do not consume.",
    targetUrl: "https://fda.gov/recalls/alert-99",
  },
  // Flooring Sample Board (Lead Arbitrage Engine Integration)
  "00850012345678:SAMPLE-HARDWOOD": {
    gtin: "00850012345678",
    lot: "SAMPLE-HARDWOOD",
    isRecalled: false,
    leadCaptureEnabled: true,
    targetUrl: "http://100.92.127.1:3000/board",
  }
};

export async function GET(
  request: NextRequest,
  context: { params: Promise<{ params?: string[] }> }
) {
  const resolvedParams = await context.params;
  const pathParams = resolvedParams.params || [];

  // Parse GS1 Key-Value Pairs
  let gtin = "";
  let lot = "";
  let serial = "";

  for (let i = 0; i < pathParams.length; i++) {
    if (pathParams[i] === "01" && pathParams[i + 1]) {
      gtin = pathParams[i + 1];
      i++;
    } else if (pathParams[i] === "10" && pathParams[i + 1]) {
      lot = pathParams[i + 1];
      i++;
    } else if (pathParams[i] === "21" && pathParams[i + 1]) {
      serial = pathParams[i + 1];
      i++;
    }
  }

  if (!gtin) {
    return NextResponse.json(
      { error: "Invalid GS1 Digital Link. Missing Application Identifier 01 (GTIN)." },
      { status: 400 }
    );
  }

  // Lookup resolution rules
  const lotKey = lot ? `${gtin}:${lot}` : gtin;
  const rule = RESOLUTION_DATABASE[lotKey] || RESOLUTION_DATABASE[gtin];

  if (!rule) {
    return NextResponse.json({
      status: "unregistered",
      gtin,
      lot: lot || null,
      message: "GS1 Digital Link valid but target brand URL not registered on resolver.",
      defaultUrl: `https://www.google.com/search?q=GTIN+${gtin}`
    });
  }

  // Handle FDA Recall Alert
  if (rule.isRecalled) {
    return NextResponse.json({
      status: "RECALLED_SAFETY_ALERT",
      warning: "⚠️ CRITICAL RECALL WARNING",
      gtin,
      lot,
      reason: rule.recallReason,
      fdaNoticeUrl: rule.targetUrl
    }, { status: 307 });
  }

  // Handle Lead Capture Integration
  if (rule.leadCaptureEnabled) {
    return NextResponse.json({
      status: "LEAD_CAPTURE_ACTIVE",
      gtin,
      lot,
      product: "Solid Hardwood 2-1/4 inch Oak",
      pricing: {
        installPerSqFt: 2.50,
        shoeMoldingPerLf: 0.25,
        sandStainRefinishPerSqFt: 1.80
      },
      message: "Scan from physical sample board detected. Instant turnaround quote available.",
      redirectUrl: rule.targetUrl
    });
  }

  // Default Redirection
  return NextResponse.redirect(rule.targetUrl, 302);
}

import { NextRequest, NextResponse } from "next/server";

export async function POST(request: NextRequest) {
  try {
    const body = await request.json();
    const {
      gtin = "00850012345678",
      sampleName = "Solid Hardwood 2-1/4 inch Oak",
      sqft = 728,
      linearFeet = 210,
      serviceType = "install_refinish", // 'install_only', 'refinish_only', 'install_refinish'
      clientName = "",
      clientPhone = "",
      clientEmail = "",
      address = ""
    } = body;

    // Rates according to Updated Business Rules
    const WASTE_FACTOR = 1.15; // 15% waste factor for corners & cuts
    const HARDWOOD_INSTALL_RATE = 2.50; // $2.50 / sq ft client billed
    const SHOE_MOLDING_INSTALL_RATE = 0.25; // $0.25 / sq ft client billed

    // Sand, Stain & Refinish Rates (Updated)
    const SAND_STAIN_REFINISH_CLIENT_RATE = 3.80; // $3.80 / sq ft client billed
    const ROMAN_SUB_REFINISH_COST = 3.12; // $3.12 / sq ft Roman sub cost

    // Billed Quantities
    const billedSqFt = Math.ceil(sqft * WASTE_FACTOR);
    const billedLinearFeet = Math.ceil(linearFeet * WASTE_FACTOR);

    let installCost = 0;
    let shoeMoldingCost = 0;
    let refinishCost = 0;

    if (serviceType === "install_only" || serviceType === "install_refinish") {
      installCost = billedSqFt * HARDWOOD_INSTALL_RATE;
      shoeMoldingCost = billedLinearFeet * SHOE_MOLDING_INSTALL_RATE;
    }

    if (serviceType === "refinish_only" || serviceType === "install_refinish") {
      refinishCost = sqft * SAND_STAIN_REFINISH_CLIENT_RATE;
    }

    const totalEstimate = installCost + shoeMoldingCost + refinishCost;

    // Subcontractor Payout (Roman's rate calculation)
    const romanInstallSubLaborRate = 1.75; // Subcontractor install labor payout rate
    const estimatedInstallSubPayout = (serviceType === "install_only" || serviceType === "install_refinish") ? sqft * romanInstallSubLaborRate : 0;
    const estimatedRefinishSubPayout = (serviceType === "refinish_only" || serviceType === "install_refinish") ? sqft * ROMAN_SUB_REFINISH_COST : 0;

    const totalSubPayout = estimatedInstallSubPayout + estimatedRefinishSubPayout;
    const netProfitMargin = totalEstimate - totalSubPayout;

    // Structure lead payload for Planka / PostgreSQL sync
    const leadPayload = {
      leadId: `QR-${Date.now().toString().slice(-6)}`,
      timestamp: new Date().toISOString(),
      gtin,
      sampleName,
      sqftInput: sqft,
      billedSqFt,
      linearFeetInput: linearFeet,
      billedLinearFeet,
      serviceType,
      pricingBreakdown: {
        hardwoodInstall: installCost.toFixed(2),
        shoeMoldingInstall: shoeMoldingCost.toFixed(2),
        sandStainRefinish: refinishCost.toFixed(2),
        totalEstimate: totalEstimate.toFixed(2),
        estimatedSubPayout: totalSubPayout.toFixed(2),
        netProfitMargin: netProfitMargin.toFixed(2)
      },
      client: {
        name: clientName || "Job Site QR Scanner",
        phone: clientPhone || "N/A",
        email: clientEmail || "N/A",
        address: address || "Scanned via Job Site QR Code"
      },
      exclusivity: {
        status: "exclusive",
        decayDays: 10,
        exclusiveUntil: new Date(Date.now() + 10 * 24 * 60 * 60 * 1000).toISOString()
      }
    };

    return NextResponse.json({
      success: true,
      message: "Lead successfully captured & synced to Lead Arbitrage Engine!",
      data: leadPayload
    }, { status: 200 });

  } catch (error: any) {
    return NextResponse.json({
      success: false,
      error: error.message || "Failed to process QR estimate lead"
    }, { status: 500 });
  }
}

