      if (!res.ok) {
        throw new Error(`Failed to load board details: ${res.status}`);
      }
      const data = await res.json();
      const included = data.included || {};

      // Sort lists
      const activeLists = (included.lists || [])
        .filter((l: { type: string; isClosed: boolean; [key: string]: unknown }) => (l.type === "active" || l.type === "list") && !l.isClosed)
        .sort((a: { position?: number }, b: { position?: number }) => (a.position || 0) - (b.position || 0));

      // Sort cards
      const activeCards = (included.cards || [])
        .filter((c: { isClosed: boolean; [key: string]: unknown }) => !c.isClosed)
        .sort((a: { position?: number }, b: { position?: number }) => (a.position || 0) - (b.position || 0));

      setLists(activeLists);
      setCards(activeCards);
    } catch (err: unknown) {
      console.error(err);
      const message = err instanceof Error ? err.message : String(err);
      setError(`Failed to sync board: ${message}`);
    } finally {
      setSyncing(false);
    }
  }, [API_BASE]);

  // Inspect deliverables & files across all boards in a project folder
  const handleInspectProject = useCallback(async (proj: Project) => {
    setInspectingProject(proj);
    setLoadingDeliverables(true);
    setProjectDeliverables([]);
    setSelectedDeliverable(null);
    try {
      const boards = proj.boards || [];
      const results = await Promise.all(
        boards.map(async (b) => {
          try {
            const res = await tenantFetch(`${API_BASE}/api/v1/planka/board/${b.id}`, { cache: "no-store" });
            if (!res.ok) return { board: b, lists: [] as Array<{ id: string; name?: string }>, cards: [] as Array<{ id: string; name?: string; description?: string; listId: string; isClosed?: boolean }> };
            const data = await res.json();
            return {
              board: b,
              lists: (data.included?.lists || []) as Array<{ id: string; name?: string }>,
              cards: (data.included?.cards || []) as Array<{ id: string; name?: string; description?: string; listId: string; isClosed?: boolean }>
            };
          } catch {
            return { board: b, lists: [] as Array<{ id: string; name?: string }>, cards: [] as Array<{ id: string; name?: string; description?: string; listId: string; isClosed?: boolean }> };
          }
        })
      );

      const allItems: DeliverableItem[] = [];
      for (const res of results) {
        const listMap = new Map<string, string>();
        for (const l of res.lists) {
          listMap.set(l.id, l.name || "List");
        }

        for (const c of res.cards) {
          if (c.isClosed) continue;
          const listName = listMap.get(c.listId) || "General";
          const lname = listName.toLowerCase();
          const isDone = lname.includes("done") || lname.includes("complete") || lname.includes("shipped") || lname.includes("verified");
          const isInProgress = !isDone && (lname.includes("progress") || lname.includes("doing") || lname.includes("testing") || lname.includes("review"));

          const desc = c.description || "";
          // Extract referenced file paths
          const fileMatches = desc.match(/(?:[a-zA-Z0-9_\-./]+\.(?:tsx?|jsx?|py|json|md|sql|ya?ml|css|html)|(?:src|core|tests|dashboard|lib)\/[a-zA-Z0-9_\-./]+)/g) || [];
          const uniqueFiles = Array.from(new Set(fileMatches)).filter(f => !f.startsWith("http") && f.length < 80);

          // Extract checklist tasks
          const taskLines = desc.split("\n").filter((line: string) => line.trim().startsWith("- [ ]") || line.trim().startsWith("- [x]") || line.trim().startsWith("- [X]"));
          const tasks = taskLines.map((line: string) => ({
            text: line.replace(/^-\s*\[[xX ]\]\s*/, "").trim(),
            done: line.includes("[x]") || line.includes("[X]")
          }));

          allItems.push({
            id: c.id,
            name: c.name || "Untitled Deliverable",
            description: desc,
            listName,
            isDone,
            isInProgress,
            boardName: res.board.name,
            boardId: res.board.id,
            files: uniqueFiles,
            tasks
          });
        }
      }

      setProjectDeliverables(allItems);
    } catch (err) {
      console.error("Failed to load project deliverables:", err);
    } finally {
      setLoadingDeliverables(false);
    }
  }, [API_BASE]);

  // Fetch comments for a specific card
  const fetchComments = useCallback(async (cardId: string) => {
    try {
      const res = await tenantFetch(`${API_BASE}/api/v1/planka/cards/${cardId}/comments`, { cache: "no-store" });
      if (!res.ok) throw new Error("Failed to load comments");
      const data = await res.json();
      const commentsList = (data.items || []).sort(
        (a: { createdAt: string }, b: { createdAt: string }) => new Date(b.createdAt).getTime() - new Date(a.createdAt).getTime()
      );
      setComments(commentsList);
    } catch (err) {
      console.error("Error loading comments:", err);
    }
  }, [API_BASE]);

  // Fetch comments for all cards on the board to aggregate in feed
  const fetchBoardComments = useCallback(async (silent = false) => {
    if (!selectedBoard || cards.length === 0) return;
    if (!silent) setLoadingComments(true);

    try {
      const allCommentsPromises = cards.map(async (card: Card): Promise<Record<string, unknown>[]> => {
        const cardController = new AbortController();
        const cardTimeout = setTimeout(() => cardController.abort(), 5000);
        const safeCardId = encodeURIComponent(String(card.id));

        try {
          const res = await tenantFetch(`${API_BASE}/api/v1/planka/cards/${safeCardId}/comments`, { 
            cache: "no-store",
            signal: cardController.signal 
          });
          if (!res.ok) return [];
          const data = await res.json();
          return (data.items || []).map((c: Record<string, unknown>) => ({
            ...c,
            cardName: card.name,
            cardId: card.id,
          }));
        } catch (err: unknown) {
          if (err instanceof Error && err.name !== "AbortError") {
            console.warn("[BOARD_FEED] Card comments load issue encountered.");
          }
          return [];
        } finally {
          clearTimeout(cardTimeout);
        }
      });

      const results = await Promise.all(allCommentsPromises);
      const aggregated = (results.flat() as { id: string; text: string; createdAt: string }[]).sort(
        (a, b) => new Date(b.createdAt).getTime() - new Date(a.createdAt).getTime()
      );

      // Shallow array comparison: only trigger React re-render if comments actually changed!
      setBoardComments(prev => {
        if (prev.length !== aggregated.length) return aggregated as BoardComment[];
        const hasChange = aggregated.some((item, i) => 
          item.id !== prev[i]?.id || item.text !== prev[i]?.text || item.createdAt !== prev[i]?.createdAt
        );
        return hasChange ? (aggregated as BoardComment[]) : prev;
      });
    } catch (err) {
      console.error("[BOARD_FEED] Global feed load error:", err);
    } finally {
      if (!silent) setLoadingComments(false);
    }
  }, [API_BASE, selectedBoard, cards]);

  // Handle card selection & side panel opening
  const handleOpenCard = useCallback((card: Card) => {
