                            </div>

                            {item.description && (
                              <div className="text-xs text-secondary/80 line-clamp-3 font-sans leading-relaxed border-l-2 border-primary/10 pl-3">
                                {item.description.replace(/<!--[\s\S]*?-->/g, "").trim() || "No detailed notes provided"}
