              if (logFilter === "warnings") {
                return upper.includes("WARN") || upper.includes("REJECTED") || upper.includes("BREACH");
              }
              if (logFilter === "tools") {
                return upper.includes("TOOL:") || upper.includes("FASTMCP") || upper.includes("HARVESTER") || upper.includes("DYNAMIC");
