      setupDPRObserver();
    };

    const setupDPRObserver = () => {
      if (dprMedia) {
        dprMedia.removeEventListener('change', handleDPRChange);
      }
      dprMedia = window.matchMedia(`(resolution: ${window.devicePixelRatio}dppx)`);
      dprMedia.addEventListener('change', handleDPRChange);
    };

