/**
 * A Sharp Step Area Chart
 */
export const SharpAreaChart = ({ data }: { data: number[] }) => {
  const [hoveredIdx, setHoveredIdx] = React.useState<number | null>(null);
  const dataMax = Math.max(...data, 0);
  const max = dataMax > 0 ? dataMax : 1;

  // Build the SVG step path
  const points: { x: number; y: number }[] = data.map((val, i) => {
    const x = (i / (data.length - 1)) * 100;
    const y = 100 - (val / max) * 90; // Leave 10% padding at top
    return { x, y };
  });

  // Build the SVG Bezier smooth spline path
  let linePath = "";
  if (points.length > 0) {
    linePath = `M ${points[0].x} ${points[0].y}`;
    for (let i = 1; i < points.length; i++) {
      const prev = points[i - 1];
      const curr = points[i];
      // Cubic Bezier interpolation control points
      const cp1X = prev.x + (curr.x - prev.x) / 3;
      const cp1Y = prev.y;
      const cp2X = prev.x + (2 * (curr.x - prev.x)) / 3;
      const cp2Y = curr.y;
      linePath += ` C ${cp1X} ${cp1Y}, ${cp2X} ${cp2Y}, ${curr.x} ${curr.y}`;
    }
  }

  const areaPath = linePath 
    ? `${linePath} L 100 100 L 0 100 Z` 
    : "";

  return (
    <div 
      className="h-full min-h-[140px] w-full relative border border-[var(--border)] bg-gradient-to-b from-[var(--background)]/10 to-[var(--background)]/40 overflow-hidden rounded-xl select-none group/chart"
      onMouseLeave={() => {
        setHoveredIdx(null);
      }}
    >
      {/* Background Blueprint Grid (Vertical & Horizontal Matrix) */}
      <div className="absolute inset-0 grid grid-cols-6 pointer-events-none opacity-[0.03]">
        {[1, 2, 3, 4, 5].map(i => <div key={i} className="border-r border-foreground" />)}
      </div>
      <div className="absolute inset-0 grid grid-rows-6 pointer-events-none opacity-[0.03]">
        {[1, 2, 3, 4, 5].map(i => <div key={i} className="border-b border-foreground" />)}
      </div>

      {/* SVG Step Chart */}
      <svg 
        className="absolute inset-0 w-full h-full p-2 pt-8 pb-1 overflow-visible"
        viewBox="0 0 100 100" 
        preserveAspectRatio="none"
      >
        <defs>
          <linearGradient id="area-gradient" x1="0" y1="0" x2="0" y2="1">
            <stop offset="0%" stopColor="var(--gold)" stopOpacity="0.25" />
            <stop offset="100%" stopColor="var(--gold)" stopOpacity="0.0" />
          </linearGradient>
        </defs>

        {/* Filled Area */}
        {areaPath && (
          <motion.path
            d={areaPath}
            fill="url(#area-gradient)"
            initial={{ opacity: 0 }}
            animate={{ opacity: 1 }}
            transition={{ duration: 0.5 }}
          />
        )}

        {/* Step Line */}
        {linePath && (
          <motion.path
            d={linePath}
            fill="none"
            stroke="var(--gold)"
            strokeWidth="1.2"
            initial={{ pathLength: 0 }}
            animate={{ pathLength: 1 }}
            transition={{ duration: 0.8, ease: "easeOut" }}
          />
        )}

        {/* Hover vertical tracking line */}
        {hoveredIdx !== null && (
          <line
            x1={points[hoveredIdx].x}
            y1={0}
            x2={points[hoveredIdx].x}
            y2={100}
            stroke="var(--gold)"
            strokeWidth="0.5"
            strokeDasharray="2 2"
            opacity="0.5"
          />
        )}

      </svg>

      {/* Perfectly round HTML Hover dot (non-stretched!) */}
      {hoveredIdx !== null && (
        <div className="absolute inset-0 pointer-events-none p-2 pt-8 pb-1 overflow-visible z-20">
          <div 
            className="absolute rounded-full w-3 h-3 bg-neutral-950 border-2 border-[var(--gold)] shadow-[0_0_8px_rgba(212,163,89,0.7)] -translate-x-1/2 -translate-y-1/2"
            style={{
              left: `${points[hoveredIdx].x}%`,
              top: `${points[hoveredIdx].y}%`
            }}
          />
        </div>
      )}

      {/* Floating HUD Tooltip */}
      <AnimatePresence>
        {hoveredIdx !== null && (
          <motion.div
            initial={{ opacity: 0, y: -4, scale: 0.95 }}
            animate={{ opacity: 1, y: 0, scale: 1 }}
            exit={{ opacity: 0, y: -4, scale: 0.95 }}
            transition={{ duration: 0.15 }}
            className="absolute top-3 left-3 z-20 px-3 py-2 bg-zinc-950/95 backdrop-blur-md border-l-2 border-l-[var(--gold)] border-t border-r border-b border-white/5 rounded-md font-mono text-[9px] flex flex-col gap-1 shadow-2xl pointer-events-none ring-1 ring-black/50"
          >
            <div className="flex justify-between items-center gap-6">
              <span className="text-stone-400 text-[7px] uppercase font-bold tracking-wider">CYCLE OFFSET</span>
              <span className="text-[var(--gold)] font-bold text-[9px]">T-{24 - hoveredIdx}H</span>
            </div>
            <div className="flex justify-between items-center gap-6">
              <span className="text-stone-400 text-[7px] uppercase font-bold tracking-wider">COMPUTE COST</span>
              <span className="font-bold text-stone-100 text-[9px]">${data[hoveredIdx].toFixed(6)}</span>
            </div>
          </motion.div>
        )}
      </AnimatePresence>

      {/* Hover Trigger Areas (Columns) */}
      <div className="absolute inset-0 flex">
        {data.map((_, i) => (
          <div
            key={i}
            className="flex-1 h-full cursor-pointer z-10"
            onMouseEnter={() => setHoveredIdx(i)}
          />
        ))}
      </div>
    </div>
  );
};




