              transition={{ type: "spring", stiffness: 300, damping: 30 }}
              className="absolute right-0 top-0 bottom-0 w-80 border-l border-border flex flex-col shrink-0 z-40 bg-card/95 backdrop-blur-xl shadow-2xl"
            >
