                                    <span className="text-[8px] font-mono text-secondary uppercase tracking-wider">Label:</span>
                                    <input
                                      type="text"
                                      value={labelValue}
                                      onChange={(e) => handleUpdateLinkLabel(selectedCard.id, item.id, e.target.value)}
