                                      className="flex-1 px-1.5 py-0.5 bg-neutral border border-border rounded text-[9px] text-primary focus:outline-none focus:border-tertiary/40"
                                      onClick={(e) => e.stopPropagation()}
                                    />
                                  </div>
                                )}
                              </div>
                            );
                          })}
                      </div>
